package com.hospital.service.impl;
import com.hospital.entity.Room; import com.hospital.exception.ResourceNotFoundException; import com.hospital.repository.RoomAllocationRepository; import com.hospital.repository.RoomRepository; import com.hospital.service.RoomService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RoomServiceImpl extends AbstractCrudService<Room> implements RoomService {
 private final RoomRepository rooms; private final RoomAllocationRepository allocations;
 public RoomServiceImpl(RoomRepository rooms,RoomAllocationRepository allocations){super(rooms);this.rooms=rooms;this.allocations=allocations;}
 @Override @Transactional public Room create(Room r){r.setRoomId(null);r.setRoomNumber(r.getRoomNumber()==null?null:r.getRoomNumber().trim());validate(r,null);r.setAvailableBeds(r.getTotalBeds());if("MAINTENANCE".equalsIgnoreCase(r.getRoomStatus()))r.setRoomStatus("MAINTENANCE");else r.setRoomStatus("AVAILABLE");return rooms.save(r);}
 @Override @Transactional public Room update(Integer id,Room r){Room current=rooms.lockById(id).orElseThrow(()->new ResourceNotFoundException("Room not found: "+id));r.setRoomNumber(r.getRoomNumber()==null?null:r.getRoomNumber().trim());validate(r,id);long occupied=allocations.countByRoomIdAndReleaseDateIsNull(id);if(r.getTotalBeds()<occupied)throw new IllegalArgumentException("Total beds cannot be lower than occupied beds.");r.setRoomId(id);r.setAvailableBeds((int)(r.getTotalBeds()-occupied));if("MAINTENANCE".equalsIgnoreCase(r.getRoomStatus())||(r.getRoomStatus()==null||r.getRoomStatus().isBlank())&&"MAINTENANCE".equalsIgnoreCase(current.getRoomStatus()))r.setRoomStatus("MAINTENANCE");else r.setRoomStatus(r.getAvailableBeds()==0?"FULL":"AVAILABLE");return rooms.save(r);}
 @Override @Transactional public void delete(Integer id){Room room=rooms.lockById(id).orElseThrow(()->new ResourceNotFoundException("Room not found: "+id));if(allocations.countByRoomId(id)>0)throw new IllegalArgumentException("Rooms with allocation history cannot be deleted.");rooms.delete(room);}
 private void validate(Room r,Integer id){if(r.getRoomNumber()==null||r.getRoomNumber().isBlank())throw new IllegalArgumentException("Room number is required.");if(r.getTotalBeds()==null||r.getTotalBeds()<1)throw new IllegalArgumentException("Total beds must be at least 1.");if(r.getRoomStatus()!=null&&!r.getRoomStatus().isBlank()&&!r.getRoomStatus().equalsIgnoreCase("AVAILABLE")&&!r.getRoomStatus().equalsIgnoreCase("FULL")&&!r.getRoomStatus().equalsIgnoreCase("MAINTENANCE"))throw new IllegalArgumentException("Room status must be AVAILABLE, FULL, or MAINTENANCE.");rooms.findByRoomNumberIgnoreCase(r.getRoomNumber().trim()).filter(existing->!existing.getRoomId().equals(id)).ifPresent(existing->{throw new IllegalArgumentException("Room number already exists.");});}
}
